<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Terms Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --surface: rgba(255, 255, 255, 0.86);
        --surface-strong: #ffffff;
        --text: #1f2937;
        --muted: #6b7280;
        --border: rgba(148, 163, 184, 0.28);
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --shadow: 0 24px 80px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 28%),
          linear-gradient(180deg, #eef4ff 0%, var(--bg) 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .card {
        width: min(100%, 480px);
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
        padding: 32px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 6px 12px;
        border-radius: 999px;
        background: rgba(37, 99, 235, 0.1);
        color: var(--accent-strong);
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 18px 0 8px;
        font-size: 2rem;
        line-height: 1.1;
      }

      p {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        margin-top: 28px;
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 10px;
        padding: 18px;
        background: var(--surface-strong);
        border: 1px solid var(--border);
        border-radius: 18px;
      }

      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: 12px;
      }

      input[type="checkbox"] {
        width: 20px;
        height: 20px;
        margin-top: 2px;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      label {
        font-weight: 600;
        line-height: 1.45;
      }

      .helper-text {
        margin-left: 32px;
        font-size: 0.95rem;
        color: var(--muted);
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        background: linear-gradient(180deg, var(--accent), var(--accent-strong));
        color: white;
        font-weight: 700;
        font-size: 1rem;
        cursor: pointer;
        box-shadow: 0 12px 28px rgba(37, 99, 235, 0.25);
        transition: transform 0.15s ease, box-shadow 0.15s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 16px 32px rgba(37, 99, 235, 0.28);
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.28);
        outline-offset: 2px;
      }

      @media (max-width: 480px) {
        .card {
          padding: 24px;
          border-radius: 20px;
        }

        h1 {
          font-size: 1.65rem;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      function h(tag, props, ...children) {
        return { tag, props: props || {}, children: children.flat() };
      }

      function mount(node) {
        if (typeof node === "string" || typeof node === "number") {
          return document.createTextNode(String(node));
        }

        if (typeof node.tag === "function") {
          return mount(node.tag(node.props || {}));
        }

        const element = document.createElement(node.tag);
        const props = node.props || {};

        Object.entries(props).forEach(([name, value]) => {
          if (name === "className") {
            element.className = value;
            return;
          }
          if (name.startsWith("on") && typeof value === "function") {
            element.addEventListener(name.slice(2).toLowerCase(), value);
            return;
          }
          if (value === true) {
            element.setAttribute(name, "");
            return;
          }
          if (value !== false && value != null) {
            element.setAttribute(name, value);
          }
        });

        node.children.forEach((child) => element.appendChild(mount(child)));
        return element;
      }

      function CheckboxField() {
        return h(
          "div",
          { className: "form-field" },
          h(
            "div",
            { className: "checkbox-row" },
            h("input", {
              id: "terms",
              name: "terms",
              type: "checkbox",
              required: true,
            }),
            h("label", { htmlFor: "terms" }, "I agree to the Terms of Use.")
          ),
          h(
            "div",
            { className: "helper-text" },
            "You must agree before submitting this form."
          )
        );
      }

      function App() {
        return h(
          "main",
          { className: "card" },
          h("div", { className: "eyebrow" }, "Consent"),
          h("h1", null, "Review and confirm"),
          h("p", null, "Please accept the terms to continue."),
          h(
            "form",
            {
              onSubmit: function (event) {
                event.preventDefault();
                alert("Thanks — your consent has been recorded.");
              },
            },
            h(CheckboxField, null),
            h("button", { type: "submit" }, "Submit")
          )
        );
      }

      document.getElementById("root").appendChild(mount(h(App)));
    </script>
  </body>
</html>
